// JUnit test to verify SSL certificate is valid
import org.junit.jupiter.api.Test;
import javax.net.ssl.HttpsURLConnection;
import javax.net.ssl.SSLContext;
import java.net.URL;
import java.security.cert.Certificate;
import java.security.cert.X509Certificate;
import java.util.Date;

public class SslCertificateTest {

    @Test
    public void verifyCertificateNotExpired() throws Exception {
        String testUrl = "https://your-domain.com";
        URL url = new URL(testUrl);
        HttpsURLConnection conn = (HttpsURLConnection) url.openConnection();
        conn.connect();

        Certificate[] certs = conn.getServerCertificates();
        for (Certificate cert : certs) {
            if (cert instanceof X509Certificate) {
                X509Certificate x509 = (X509Certificate) cert;
                Date expiry = x509.getNotAfter();
                Date now = new Date();

                assertTrue(expiry.after(now), 
                    "Certificate expired on " + expiry);

                // Verify at least 7 days until expiration
                long daysUntilExpiry = (expiry.getTime() - now.getTime()) 
                    / (1000 * 60 * 60 * 24);
                assertTrue(daysUntilExpiry > 7, 
                    "Certificate expires in " + daysUntilExpiry + " days");
            }
        }

        conn.disconnect();
    }
}

