// Mocha/Chai test for SSL certificate validity
const https = require('https');
const { expect } = require('chai');

describe('SSL Certificate Tests', () => {
  it('should have valid non-expired certificate', (done) => {
    const options = {
      hostname: 'your-domain.com',
      port: 443,
      path: '/',
      method: 'GET'
    };

    const req = https.request(options, (res) => {
      const cert = res.socket.getPeerCertificate();

      // Check certificate exists
      expect(cert).to.exist;

      // Check expiration date
      const validTo = new Date(cert.valid_to);
      const now = new Date();

      expect(validTo.getTime()).to.be.greaterThan(now.getTime());

      // Check at least 7 days until expiration
      const daysUntilExpiry = (validTo - now) / (1000 * 60 * 60 * 24);
      expect(daysUntilExpiry).to.be.greaterThan(7);

      done();
    });

    req.on('error', (e) => {
      done(e);
    });

    req.end();
  });
});

