// ASP.NET Core - Update SSL certificate in Program.cs
using Microsoft.AspNetCore.Server.Kestrel.Core;
using Microsoft.AspNetCore.Server.Kestrel.Https;
using System.Security.Cryptography.X509Certificates;

var builder = WebApplication.CreateBuilder(args);

// Configure Kestrel to use new certificate
builder.WebHost.ConfigureKestrel(serverOptions =>
{
    serverOptions.ConfigureHttpsDefaults(httpsOptions =>
    {
        // Load certificate from file
        httpsOptions.ServerCertificate = new X509Certificate2(
            "path/to/certificate.pfx", 
            "certificate-password"
        );

        // Or load from certificate store
        // httpsOptions.ServerCertificate = LoadCertificateFromStore();
    });
});

var app = builder.Build();
app.UseHttpsRedirection();
app.Run();

// Helper method to load from Windows Certificate Store
X509Certificate2 LoadCertificateFromStore()
{
    using var store = new X509Store(StoreName.My, StoreLocation.LocalMachine);
    store.Open(OpenFlags.ReadOnly);
    var certs = store.Certificates.Find(
        X509FindType.FindByThumbprint,
        "YOUR_CERTIFICATE_THUMBPRINT",
        validOnly: true
    );
    return certs[0];
}

