// xUnit test for SSL certificate validation
using Xunit;
using System.Net.Http;
using System.Security.Cryptography.X509Certificates;

public class SslCertificateTests
{
    [Fact]
    public async Task Certificate_Should_Not_Be_Expired()
    {
        var handler = new HttpClientHandler
        {
            ServerCertificateCustomValidationCallback = 
                (message, cert, chain, errors) =>
                {
                    // Capture certificate for testing
                    var x509Cert = cert as X509Certificate2;
                    Assert.NotNull(x509Cert);

                    // Verify not expired
                    Assert.True(x509Cert.NotAfter > DateTime.Now,
                        $"Certificate expired on {x509Cert.NotAfter}");

                    // Verify at least 7 days until expiration
                    var daysUntilExpiry = 
                        (x509Cert.NotAfter - DateTime.Now).TotalDays;
                    Assert.True(daysUntilExpiry > 7,
                        $"Certificate expires in {daysUntilExpiry} days");

                    return true;
                }
        };

        using var client = new HttpClient(handler);
        var response = await client.GetAsync("https://your-domain.com");
        response.EnsureSuccessStatusCode();
    }
}

