// Selenium test for SSL certificate validation
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.testng.annotations.Test;
import org.testng.Assert;

public class SslCertificateTest {

    @Test
    public void verifySecureConnection() {
        ChromeOptions options = new ChromeOptions();
        // Don't ignore certificate errors in test
        options.setAcceptInsecureCerts(false);

        WebDriver driver = new ChromeDriver(options);

        try {
            // This will fail if certificate is invalid/expired
            driver.get("https://your-domain.com");

            // Verify we're on HTTPS
            String currentUrl = driver.getCurrentUrl();
            Assert.assertTrue(currentUrl.startsWith("https://"),
                "Connection should use HTTPS");

            // Verify page loaded successfully
            Assert.assertFalse(driver.getTitle().isEmpty(),
                "Page should load successfully");

        } finally {
            driver.quit();
        }
    }

    @Test
    public void verifyNoMixedContent() {
        ChromeDriver driver = new ChromeDriver();

        try {
            driver.get("https://your-domain.com");

            // Check console for mixed content warnings
            LogEntries logs = driver.manage().logs().get(LogType.BROWSER);
            for (LogEntry entry : logs) {
                Assert.assertFalse(
                    entry.getMessage().contains("Mixed Content"),
                    "Page should not load insecure resources"
                );
            }
        } finally {
            driver.quit();
        }
    }
}
